use axiom_learning::journey::{self,StudyAction};
fn main(){let day: i64=std::env::args().nth(1).unwrap().parse().unwrap();let id=journey::catalog()[0].id.clone();let mut state=journey::action(Default::default(),StudyAction::AcknowledgeLesson{step_id:id.clone()},day).unwrap();state=journey::action(state,StudyAction::Reflection{step_id:id,recorded:true},day).unwrap();for seed in [1,2]{let p=axiom_math::generate("place_value.decompose","1.1.0",&format!("{seed:064x}"),1,"test").unwrap();let grade=axiom_math::check(&p,p.target_value.as_ref().unwrap(),&Default::default());state=journey::record(state,&p,&grade,false,day).unwrap()}println!("{}",serde_json::json!({"view":journey::snapshot(&state,day).unwrap(),"state":state}))}
